```js
import { customAlphabet } from "nanoid/non-secure";
const nanoid = customAlphabet("1234567890abcdef", 10);
user.id = nanoid();
```

在我们的 [ID 碰撞概率] 计算器中检查您的自定义字母表和 ID 大小的安全性。
查看 [`nanoid-dictionary`] 中的选项以获取更多字母表。

字母表必须包含256个或更少的符号。
否则，无法保证内部生成器算法的安全性。

除了设置默认大小外，您还可以在调用函数时更改ID大小：

```js
import { customAlphabet } from "nanoid";
const nanoid = customAlphabet("1234567890abcdef", 10);
model.id = nanoid(5); //=> "f01a2"
```

[ID collision probability]: https://zelark.github.io/nano-id-cc/
[`nanoid-dictionary`]: https://github.com/CyberAP/nanoid-dictionary

### 自定义随机字节生成器

`customRandom` 允许您创建一个 `nanoid` 并替换字母表
和默认的随机字节生成器。

在此示例中，使用基于种子的生成器:

```js
import { customRandom } from "nanoid";

const rng = seedrandom(seed);
const nanoid = customRandom("abcdef", 10, (size) => {
  return new Uint8Array(size).map(() => 256 * rng());
});

nanoid(); //=> "fbaefaadeb"

    nanoid2(2.1)
    let second = nanoid2()
    let third = nanoid2()
    notEqual(second, third)
  })

  test(`supports multi-byte characters`, () => {
    let ALPHABET = 'абвгд'
    let nanoid2 = customAlphabet(ALPHABET, 10)
    for (let i = 0; i < 100; i++) {
      let id = nanoid2()
      equal(id.length, 10)
      for (let char of id) {
        ok(ALPHABET.includes(char))
      }
    }
  })

  test(`supports alphabets bigger than 256 symbols`, () => {
    equal(customAlphabet('a'.repeat(300))(0), '')
  })

  test(`supports non-string alphabets`, () => {
    let ALPHABET = ['a', 'b', 'c', 'd']
    let nanoid2 = customAlphabet(ALPHABET, 10)
    let id = nanoid2()
    equal(id.length, 10)
    for (let char of id) {
      ok(ALPHABET.includes(char))
    }
  })

  if (type === 'node') {
    test(`does not fall in infinite loop`, () => {
      equal(customAlphabet('abc')(0), '')
      equal(customAlphabet('abc', 0)(0), '')
    })
  }
})

